var router23 = new Hono2();
router23.use("*", requireAuth);
async function assertTaskOwnership(taskId, workspaceId) {
  const { data } = await supabase.from("tasks").select("id").eq("id", taskId).eq("workspace_id", workspaceId).single();
  if (!data) throw new Error("Task not found or access denied");
}
router23.get("/:id/reviews", async (c) => {
  try {
    await assertTaskOwnership(c.req.param("id"), c.get("workspaceId"));
  } catch {
    return c.json({ error: "Not found" }, 404);
  }
  const { data, error } = await supabase.from("task_reviews").select("*").eq("task_id", c.req.param("id")).order("round", { ascending: true });
  if (error) return c.json({ error: error.message }, 500);
  return c.json(data ?? []);
});
router23.post("/:id/reviews", async (c) => {
  const userId = c.get("userId");
  const workspaceId = c.get("workspaceId");
  try {
    await assertTaskOwnership(c.req.param("id"), workspaceId);
  } catch {
    return c.json({ error: "Not found" }, 404);
  }
  const body = await c.req.json();
  const { count } = await supabase.from("task_reviews").select("*", { count: "exact", head: true }).eq("task_id", c.req.param("id"));
  const round = (count || 0) + 1;
  await supabase.from("task_reviews").update({ status: "completed", action: "reassigned", action_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("task_id", c.req.param("id")).eq("status", "pending");
  const { data, error } = await supabase.from("task_reviews").insert({
    task_id: c.req.param("id"),
    round,
    sent_by_id: userId,
    sent_by_name: body.sent_by_name,
    context: body.context,
    reviewer_id: body.reviewer_id,
    reviewer_name: body.reviewer_name,
    status: "pending"
  }).select().single();
  if (error) return c.json({ error: error.message }, 500);
  await supabase.from("tasks").update({
    status: "review",
    reviewer_id: body.reviewer_id,
    reviewer_name: body.reviewer_name,
    review_result: null
  }).eq("id", c.req.param("id"));
  await supabase.from("notifications").insert({
    workspace_id: workspaceId,
    user_id: body.reviewer_id,
    title: `Review requested (Round ${round})`,
    body: `${body.sent_by_name} sent you a task for review: "${body.context.slice(0, 60)}${body.context.length > 60 ? "..." : ""}"`,
    type: "review",
    task_id: c.req.param("id"),
    is_read: false
  });
  await supabase.from("task_activity").insert({
    task_id: c.req.param("id"),
    user_id: userId,
    user_name: body.sent_by_name,
    action: `sent task for review to ${body.reviewer_name} (Round ${round}): "${body.context.slice(0, 60)}${body.context.length > 60 ? "..." : ""}"`
  });
  return c.json(data, 201);
});
router23.patch("/:id/reviews/:reviewId", async (c) => {
  const userId = c.get("userId");
  const workspaceId = c.get("workspaceId");
  try {
    await assertTaskOwnership(c.req.param("id"), workspaceId);
  } catch {
    return c.json({ error: "Not found" }, 404);
  }
  const body = await c.req.json();
  const { data: review } = await supabase.from("task_reviews").update({
    action: body.action,
    action_note: body.action_note || null,
    action_at: (/* @__PURE__ */ new Date()).toISOString(),
    status: "completed"
  }).eq("id", c.req.param("reviewId")).select().single();
  let commentText = "";
  if (body.action === "approved") {
    commentText = `Task approved by ${body.reviewer_name}.${body.action_note ? `

Note: ${body.action_note}` : ""}`;
  } else if (body.action === "changes_requested") {
    commentText = `Changes requested by ${body.reviewer_name}.

${body.action_note || "Please review and update before resubmitting."}`;
  } else if (body.action === "reassigned") {
    commentText = `Review reassigned by ${body.reviewer_name} to ${body.new_reviewer_name}.${body.action_note ? `

Note: ${body.action_note}` : ""}`;
  }
  if (commentText) {
    await supabase.from("task_activity").insert({
      task_id: c.req.param("id"),
      user_id: userId,
      user_name: body.reviewer_name,
      action: body.action === "approved" ? `approved the task${body.action_note ? `: "${body.action_note}"` : ""}` : body.action === "changes_requested" ? `requested changes: "${body.action_note || "please review and update"}"` : `reassigned review to ${body.new_reviewer_name}`
    });
  }
  if (body.action === "approved") {
    await supabase.from("tasks").update({
      review_result: "approved",
      reviewed_at: (/* @__PURE__ */ new Date()).toISOString(),
      status: "in_progress",
      labels: []
    }).eq("id", c.req.param("id"));
  } else if (body.action === "changes_requested") {
    await supabase.from("tasks").update({
      status: "in_progress",
      review_result: "changes_requested",
      reviewer_id: null,
      reviewer_name: null,
      reviewed_at: (/* @__PURE__ */ new Date()).toISOString()
    }).eq("id", c.req.param("id"));
  } else if (body.action === "reassigned" && body.new_reviewer_id) {
    const { count } = await supabase.from("task_reviews").select("*", { count: "exact", head: true }).eq("task_id", c.req.param("id"));
    await supabase.from("task_reviews").insert({
      task_id: c.req.param("id"),
      round: (count || 0) + 1,
      sent_by_id: userId,
      sent_by_name: body.reviewer_name,
      context: body.context || "",
      reviewer_id: body.new_reviewer_id,
      reviewer_name: body.new_reviewer_name || "",
      status: "pending"
    });
    await supabase.from("tasks").update({
      reviewer_id: body.new_reviewer_id,
      reviewer_name: body.new_reviewer_name
    }).eq("id", c.req.param("id"));
    await supabase.from("notifications").insert({
      workspace_id: workspaceId,
      user_id: body.new_reviewer_id,
      title: "Review reassigned to you",
      body: `${body.reviewer_name} reassigned a task review to you`,
      type: "review",
      task_id: c.req.param("id"),
      is_read: false
    });
  }
  if (body.action !== "reassigned") {
    await supabase.from("notifications").insert({
      workspace_id: workspaceId,
      user_id: body.owner_id,
      title: body.action === "approved" ? "Task Approved" : "Changes Requested",
      body: body.action === "approved" ? `${body.reviewer_name} approved your task` : `${body.reviewer_name} requested changes: ${(body.action_note || "").slice(0, 80)}`,
      type: "review",
      task_id: c.req.param("id"),
      is_read: false
    });
  }
  return c.json(review);
});

