// src/routes/import.ts
var router25 = new Hono2();
var importBodySchema = external_exports.object({
  headers: external_exports.array(external_exports.string()),
  samples: external_exports.array(external_exports.array(external_exports.string())),
  // first 3 rows for schema inference
  rows: external_exports.array(external_exports.array(external_exports.string())),
  // all rows to insert
  object_type: external_exports.string().min(1),
  vertical: external_exports.enum(["sales", "realestate", "hr", "finance", "investments", "tasks", "shared"]).default("shared")
});
router25.post("/", requireAuth, zValidator("json", importBodySchema), async (c) => {
  const { headers, samples, rows: rows2, object_type, vertical } = c.req.valid("json");
  const workspaceId = c.get("workspaceId");
  const userId = c.get("userId");
  let columnTypes = {};
  try {
    const sampleText = [headers.join(","), ...samples.map((r) => r.join(","))].join("\n");
    const inferRes = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": process.env.ANTHROPIC_API_KEY ?? "",
        "anthropic-version": "2023-06-01",
        "content-type": "application/json"
      },
      body: JSON.stringify({
        model: "claude-haiku-4-5-20251001",
        max_tokens: 512,
        messages: [{
          role: "user",
          content: `You are a data schema expert. Given the following CSV headers and sample rows, classify each column as one of: Text, Number, Email, URL, Date, Status, Currency, Phone, Boolean.

CSV:
${sampleText}

Reply with ONLY a JSON object mapping each header to its type. Example: {"name":"Text","revenue":"Currency","active":"Boolean"}`
        }]
      })
    });
    if (inferRes.ok) {
      const inferJson = await inferRes.json();
      const text = inferJson.content?.find((b) => b.type === "text")?.text ?? "{}";
      const parsed = JSON.parse(text.trim());
      if (typeof parsed === "object" && parsed !== null) {
        columnTypes = parsed;
      }
    }
  } catch {
  }
  function coerce2(value, type) {
    const v = value.trim();
    if (!v) return null;
    switch (type) {
      case "Number":
      case "Currency": {
        const n = parseFloat(v.replace(/[^0-9.\-]/g, ""));
        return isNaN(n) ? v : n;
      }
      case "Boolean":
        return /^(true|yes|1|on)$/i.test(v);
      default:
        return v;
    }
  }
  const safeType = object_type.toLowerCase().replace(/\s+/g, "_").replace(/[^a-z0-9_-]/g, "");
  const created = [];
  const errors = [];
  for (let i = 0; i < rows2.length; i++) {
    const row = rows2[i];
    const data = {};
    headers.forEach((h, j) => {
      const key = h.trim().toLowerCase().replace(/\s+/g, "_").replace(/[^a-z0-9_]/g, "");
      if (key) data[key] = coerce2(row[j] ?? "", columnTypes[h] ?? "Text");
    });
    if (!data.name && !data.title && !data.email) {
      data.name = row[0] ?? `Row ${i + 1}`;
    }
    try {
      const node = await createNode({ workspace_id: workspaceId, created_by: userId, vertical, object_type: safeType, data });
      created.push(node.id);
    } catch (e) {
      errors.push({ row: i + 1, error: e?.message ?? "unknown error" });
    }
  }
  const ENRICHABLE2 = ["contact", "person", "people", "lead", "company", "account", "organization"];
  if (ENRICHABLE2.some((t) => safeType.toLowerCase().includes(t))) {
    for (const nodeId of created) {
      inngest.send({
        name: "crm/record.created",
        data: { workspaceId, nodeId, objectType: safeType, vertical, recordData: {} }
      }).catch(() => {
      });
    }
  }
  return c.json({ ok: true, created: created.length, errors, column_types: columnTypes, auto_enriching: ENRICHABLE2.some((t) => safeType.toLowerCase().includes(t)) }, 201);
});

// src/routes/generate.ts
var router26 = new Hono2();
async function callAnthropic(body) {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error("Anthropic API key not configured");
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-api-key": apiKey, "anthropic-version": "2023-06-01" },
    body: JSON.stringify(body)
  });
  if (!res.ok) throw new Error(`Anthropic error: ${await res.text()}`);
  return res.json();
}
router26.post("/schema", requireAuth, zValidator("json", external_exports.object({ prompt: external_exports.string().min(1) })), async (c) => {
  const { prompt } = c.req.valid("json");
  try {
    const data = await callAnthropic({
      model: "claude-haiku-4-5-20251001",
      max_tokens: 2048,
      tools: [{
        name: "create_object_schema",
        description: "Create a Mondaily object schema with attributes for the described use case",
        input_schema: {
          type: "object",
          properties: {
            singular: { type: "string", description: "Singular name e.g. Invoice" },
            plural: { type: "string", description: "Plural name e.g. Invoices" },
            vertical: { type: "string", enum: ["sales", "finance", "hr", "realestate", "investments", "shared"] },
            color: { type: "string", enum: ["red", "orange", "amber", "emerald", "cyan", "blue", "violet", "pink"] },
            description: { type: "string", description: "One-line description of what this tracks" },
            attributes: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  name: { type: "string" },
                  type: { type: "string", enum: ["text", "long_text", "number", "currency", "percentage", "date", "datetime", "checkbox", "select", "multi_select", "url", "email", "phone"] }
                },
                required: ["name", "type"]
              },
              minItems: 5,
              maxItems: 14
            }
          },
          required: ["singular", "plural", "vertical", "color", "attributes"]
        }
      }],
      tool_choice: { type: "tool", name: "create_object_schema" },
      messages: [{
        role: "user",
        content: `Create a comprehensive Mondaily object schema for: ${prompt}

Use appropriate field types: currency for money, date for dates, checkbox for yes/no, select for status/category, percentage for rates, number for quantities.`
      }]
    });
    const toolUse = data.content?.find((b) => b.type === "tool_use");
    if (!toolUse?.input) return c.json({ error: "No schema generated" }, 500);
    return c.json(toolUse.input);
  } catch (e) {
    return c.json({ error: e.message }, 500);
  }
});
